export function buildSql(){
 let sql=`SET NOCOUNT ON; SET XACT_ABORT ON; ${IDENTITY}
DECLARE @definition nvarchar(max);
IF @@TRANCOUNT=0 THROW 51230,'WORK_PAYMENT_OPERATOR_TRANSACTION_REQUIRED',1;
IF (SELECT transaction_isolation_level FROM sys.dm_exec_sessions WHERE session_id=@@SPID)<>4 THROW 51230,'WORK_PAYMENT_SERIALIZABLE_REQUIRED',1;
IF IS_SRVROLEMEMBER(N'sysadmin') IS NULL OR IS_SRVROLEMEMBER(N'sysadmin')<>1 THROW 51230,'WORK_PAYMENT_OPERATOR_REQUIRED',1;
${principal}\n${baseline}
IF OBJECT_ID(N'dbo.work_finops_scope',N'U') IS NOT NULL BEGIN
IF OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_work_supplier_payment_ready')) IS NULL OR CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.usp_work_supplier_payment_ready'))),2)<>N'${WORK_SUPPLIER_PAYMENT_SQL_PROOF.readyHash}' ${fail}
EXEC dbo.usp_work_supplier_payment_ready; SELECT CAST(0 AS bit) installed; RETURN; END;
${[...TABLE_NAMES,...Object.keys(GUARDS),'usp_work_supplier_payment_ready','usp_work_supplier_payment_context','usp_work_supplier_payment_effects'].map(n=>`IF OBJECT_ID(N'dbo.${n}') IS NOT NULL THROW 51230,'WORK_PAYMENT_PARTIAL_INSTALL',1;`).join('\n')}
DECLARE @receiptSeed bigint,@reserve bigint,@reserveLock int;
EXEC @reserveLock=sys.sp_getapplock @Resource=N'MELISA-TEST-V70-SALES',@LockMode=N'Exclusive',@LockOwner=N'Transaction',@LockTimeout=15000;
IF @reserveLock<0 THROW 51230,'WORK_PAYMENT_LOCK',1;
SELECT TOP(1) @reserve=id FROM dbo.stock_movements WITH(TABLOCKX,HOLDLOCK) ORDER BY id;
SELECT TOP(1) @reserve=id FROM dbo.test_goods_receipts WITH(TABLOCKX,HOLDLOCK) ORDER BY id;
SELECT TOP(1) @reserve=id FROM dbo.test_daily_drafts WITH(TABLOCKX,HOLDLOCK) ORDER BY id;
SELECT @receiptSeed=COALESCE(MAX(id),0)+1 FROM(SELECT id FROM dbo.test_goods_receipts UNION ALL SELECT id FROM dbo.test_daily_drafts UNION ALL SELECT source_id FROM dbo.stock_movements WHERE source_type=N'goods_receipt' AND source_id IS NOT NULL) ids;
IF @receiptSeed IS NULL OR @receiptSeed<=0 OR @receiptSeed>9007199254740991 THROW 51230,'WORK_PAYMENT_RECEIPT_NAMESPACE',1;
SET @definition=REPLACE(REPLACE(REPLACE(CAST(${lit(TABLE_SQL)} AS nvarchar(max)),N'__FINOPS_RECEIPT_SEED__',CONVERT(varchar(20),@receiptSeed)),CHAR(13)+CHAR(10),CHAR(10)),CHAR(13),CHAR(10)); EXEC(@definition);
${SEED_SQL}`;
 const definitions={...GUARDS,usp_work_supplier_payment_ready:readyDefinition(),usp_work_supplier_payment_context:contextDefinition(),usp_work_supplier_payment_effects:effectsDefinition()};
 for(const [name,definition] of Object.entries(definitions)){
  if(name!=='work_finops_manifest_guard')sql+=`\n${executeDefinition(definition)}`;
  sql+=`\nINSERT dbo.work_finops_manifest(name,definition_hash) VALUES(${lit(name)},${lit(hash(definition))});`;
 }
 // The immutable manifest is created last, after every pinned row is populated.
 sql+=`\nINSERT dbo.work_finops_manifest(name,definition_hash) VALUES(N'__schema__',(${SCHEMA_SQL}));\n${executeDefinition(GUARDS.work_finops_manifest_guard)}
${PERMISSIONS.map(([n,p,s])=>`${s==='G'?'GRANT':'DENY'} ${p} ON dbo.${n} TO [melisa_sirket_sales_test_20260929_01];`).join('\n')}
EXEC dbo.usp_work_supplier_payment_ready;
IF @oldModuleHash<>CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT o.schema_id,o.name,o.type,m.definition,t.is_disabled FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id LEFT JOIN sys.triggers t ON t.object_id=o.object_id WHERE o.object_id NOT IN(${[...Object.keys(GUARDS),'usp_work_supplier_payment_ready','usp_work_supplier_payment_context','usp_work_supplier_payment_effects'].map(n=>`OBJECT_ID(N'dbo.${n}')`).join(',')}) ORDER BY o.schema_id,o.name FOR JSON PATH,INCLUDE_NULL_VALUES)),2) THROW 51230,'WORK_PAYMENT_OLD_MODULE_CHANGED',1;
IF @dbPermissionsBefore<>CONVERT(varchar(64),HASHBYTES('SHA2_256',(SELECT * FROM sys.database_permissions WHERE major_id NOT IN(${[...TABLE_NAMES,'usp_work_supplier_payment_ready','usp_work_supplier_payment_context','usp_work_supplier_payment_effects'].map(n=>`OBJECT_ID(N'dbo.${n}')`).join(',')}) ORDER BY class,major_id,minor_id,grantee_principal_id,type FOR JSON PATH,INCLUDE_NULL_VALUES)),2) THROW 51230,'WORK_PAYMENT_OTHER_PERMISSION_CHANGED',1;
SELECT CAST(1 AS bit) installed,N'${RUN}' run_id,CONVERT(varchar(20),@supplier) supplier_id,CONVERT(varchar(20),@account) account_id,CONVERT(varchar(20),@product) product_id,CONVERT(varchar(20),@receipt) receipt_id,CONVERT(varchar(20),@invoice) invoice_id,@oldScopes old_scope_hash,@oldModuleHash old_module_hash,@rolePermissionsBefore role_permission_hash,@dbPermissionsBefore other_database_permission_hash,(SELECT * FROM @protected ORDER BY name FOR JSON PATH) protected_rows_json;`;
 return sql;
}
if(process.argv[1]&&path.resolve(process.argv[1])===fileURLToPath(import.meta.url)&&process.argv.includes('--write')){
 fs.writeFileSync(new URL('./enable-test-work-finops-fixture.sql',import.meta.url),buildSql());
 fs.writeFileSync(new URL('../../apps/api/src/services/workSupplierPaymentSqlProof.mjs',import.meta.url),`// Generated offline from owned definitions, never from the running database.\nexport const WORK_SUPPLIER_PAYMENT_SQL_PROOF=Object.freeze(${JSON.stringify(WORK_SUPPLIER_PAYMENT_SQL_PROOF,null,2)});\n`);
}
